		public DataTable GetStudentCautionMoneyDetails(int aiStudentID, int aiAcademicYrID, int aiSchoolID)
		{
			string sSelectStatement = " SELECT  " +
				"Student_Caution_Money_Id" +
				",Student_Caution_Money_Details.School_Id" +
				",Student_Caution_Money_Details.Schoolwise_Student_Id" +
				",Amount" +
                ",ConcessionAmount" +
				",Paid_By_Student" +
				",Payment_Date" +
				",Returned_By_School" +
				",Return_Date" +
				",Payment_Mode" +
				",Payment_Cheque_Id" +
				",Return_Cheque_Id" +
				",SchoolWise_Student_Master.Admission_Date " +
			" FROM Student_Caution_Money_Details INNER JOIN YearWise_Student_Details" +
			" ON Student_Caution_Money_Details.Schoolwise_Student_Id=YearWise_Student_Details.Student_Id " +
			" INNER JOIN SchoolWise_Student_Master " +
			" ON YearWise_Student_Details.Student_Id =SchoolWise_Student_Master.SchoolWise_Student_Id " +
			" WHERE " +
			" YearWise_Student_Details.YearWise_Student_Id=" + aiStudentID +
			" AND Student_Caution_Money_Details.School_Id=" + aiSchoolID +
			" AND SchoolWise_Student_Master.School_Id=" + aiSchoolID +
			" AND YearWise_Student_Details.Academic_Year_ID=" + aiAcademicYrID +
			" AND SchoolWise_Student_Master.Is_Deleted='" + Utility.Constants.C_NO + "'" +
			" AND Student_Caution_Money_Details.Is_Deleted = 0";
			using (SQLServerDbUtility oSQLServerDbUtility = new SQLServerDbUtility())
				return oSQLServerDbUtility.ExecuteSqlStatementAndGetDataTable(sSelectStatement);
		}

